A.append(mk(
    'parsha-behar-young-the-land-needs-rest-too', 'בהר: גם לארץ מגיעה מנוחה', (3, 6), 40,
    ['פרשת בהר', 'שמיטה', 'הכרת הטוב'], ['מנוחה', 'שיתוף', 'אחריות'], ['פרשת שבוע', 'בהר', 'בהר-בחוקותי', 'שמיטה', 'מנוחה', 'שיתוף', 'גיל צעיר'],
    'התורה מצווה שבכל שנה שביעית הארץ תנוח, ושהפירות שצומחים יהיו לכולם. הפעולה מלמדת על שמיטה, על מנוחה, ועל הרעיון שהדברים הגדולים באמת מושאלים לנו ואנחנו שומרים עליהם.',
    ['הילדים יכירו את מצוות שנת השמיטה ואת הרעיון "הארץ נחה"', 'הילדים יבינו את המשפט "כי לי הארץ" — שהדברים שבידינו מושאלים', 'כל ילד יבחר דבר אחד שיתן לו מנוחה ודבר אחד שישתף עם אחרים'],
    ('שואלים: "מה קורה לכם כשאתם עייפים מאוד ולא ישנים? ומה קורה אחרי מנוחה?" אוספים תשובות. אומרים: היום נלמד שגם לארץ מגיעה מנוחה.', 5),
    [
        ('שנה שביעית', 'מספרים: התורה מצווה שאחרי שש שנים שבהן עובדים את האדמה, השנה השביעית היא שנה של שבת לארץ: "' + V['L25_4'] + '". בשנה הזאת לא זורעים ולא קוצרים כרגיל, והפירות שצומחים מעצמם אפשר לאכול כולם. אחר כך אומרת התורה: "' + V['L25_23'] + '". שואלים: למה, לדעתכם, כתוב שאנחנו "גרים ותושבים"? מה הרעיון?', 8),
        ('משחק שנת השמיטה', 'מחלקים את הילדים ל"חקלאים" ו"פירות". בשישה סיבובים של דקה החקלאים "עובדים" (חורשים, זורעים, מקצרים במחוות) והפירות משחקים צמחים שגדלים. בסיבוב השביעי: כולם מתיישבים ונחים, ו"פירות" שצמחו לבד — כל ילד לוקח פרי אחד ושם בסל באמצע, וכל אחד יכול לקחת ממנו. שואלים: מה היה הבדל בין שישה הסיבובים הראשונים לשביעי?', 8),
        ('"שלי" או "מושאל"?', 'כל ילד מצייר יד ועל כל אצבע כותב או מצייר דבר שהוא מרגיש שהוא "שלו" (צעצוע, אופניים, משפחה, ים). אחר כך שואלים: מי נתן? מי עוזר לשמור? האם אפשר להחליט שכל דבר בשבילי? אוספים ממה שהילדים אומרים ומסכמים: הרבה דברים מושאלים לנו, ולכן שומרים עליהם ומשתפים.', 12),
    ],
    ['מה דומה בין מנוחה של ילד למנוחה של הארץ?', 'למה חשוב לשתף ולא רק לשמור לעצמנו?', 'מה אפשר לעשות בלי לחכות לשנה שביעית כדי לתת לעולם לנוח?'],
    'כל ילד אומר: "השבוע אני נותן מנוחה ל... ומשתף את..." ומקבל מחיאת כף.',
    'לפני: הפעולה עוסקת ברעיון, לא בהלכות שמיטה בימינו. אל תיכנסו למחלוקות או לשאלות על דרכי קיום המצווה.\nמשחק: ודאו שסיבוב ה"פירות" נעשה בשקט, בלי הדחיפות. אפשר להשתמש בדפים צבעוניים כפירות.\nשיתוף: יש ילדים ממשפחות עם פחות אפשרויות; הדגישו שמשתפים גם זמן ומילים טובות, לא רק חפצים.\nהקשר: אפשר להזכיר שהיובל היא שנה מיוחדת של "דרור", אבל לא להרחיב.',
    'אפשר לתכנן יום "שמיטה" בסניף: פעילות בלי מסכים או הפסקה מיוחדת לכולם.',
    game=('"קפוא ונח": הילדים רצים או מסתובבים לקצב מחיאות כף. כשהמדריך אומר "שמיטה!" — כולם קופאים, עוצמים עיניים ונושמים עמוק שלוש נשימות. אחר כך ממשיכים. מסיימים בשאלה: איך הרגשתם בזמן המנוחה?', 4),
    sourceLink=('ויקרא כה — שנת השמיטה (ספריא)', SEF + 'Leviticus.25'),
    equipment=['דפים וצבעים', 'סל', 'דפים צבעוניים בצורת פירות'], shabbat='שניהם', place='פנים', energy='בינונית', depth='קליל', rating=4.5, character='A', groupSize='8-24 ילדים',
    shabbatNote='בשבת מציירים בדמיון: כל ילד מתאר בעל פה את "היד" שלו (חמישה דברים מושאלים), והקבוצה מקשיבה.',
))

